WITH kept_keys AS (SELECT id, channel FROM promotions INTERSECT ALL SELECT id, channel FROM promotions WHERE discount_pct < 0.32), kept_rows AS (SELECT s.* FROM promotions s INNER JOIN kept_keys k ON s.id = k.id AND s.channel = k.channel), filtered AS (SELECT id, channel, ends_on, discount_pct, ROUND(discount_pct, 0) AS discount_pct_rounded, SUBSTRING(promo_code, 1, 3) AS promo_code_prefix FROM kept_rows WHERE ends_on > TO_DATE('2023-06-09')), metrics AS (SELECT id, channel, ends_on, discount_pct, discount_pct_rounded, promo_code_prefix, ROUND(discount_pct / SUM(discount_pct) OVER (PARTITION BY channel), 4) AS discount_pct_share, RANK() OVER (PARTITION BY channel ORDER BY discount_pct_rounded DESC NULLS LAST) AS discount_pct_rounded_rank, STDDEV_SAMP(discount_pct_rounded) OVER (PARTITION BY DATE_TRUNC('week', ends_on), channel) AS ends_on_period_stddev_samp_discount_pct_rounded FROM filtered), matched AS (SELECT e.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct AS promotion_discount_pct FROM metrics e INNER JOIN promotions pr ON e.channel = pr.channel AND e.ends_on >= pr.starts_on AND e.ends_on <= DATE_ADD(pr.ends_on, 10)), pivoted AS (SELECT * FROM (SELECT channel, promo_code, discount_pct FROM matched) src PIVOT (SUM(discount_pct) FOR promo_code IN ('SPRING10', 'WELCOME5', 'VIP'))) SELECT channel, SPRING10, WELCOME5, VIP, CASE WHEN channel RLIKE '^(store|web)$' THEN 'CORE' ELSE 'GROUP_A' END AS channel_zone FROM pivoted ORDER BY channel_zone DESC;
